81	export function AdminActivityTables({
82	  sessions,
83	  payments,
84	  payouts,
85	}: {
86	  sessions: AdminSessionRow[];
87	  payments: AdminPaymentRow[];
88	  payouts: AdminPayoutRow[];
89	}) {
90	  const sessionCols: Column<AdminSessionRow>[] = [
91	    { key: "dateLabel", header: t("admin.colDate"), sortable: true, sortValue: (r) => r.dateMs },
92	    { key: "durationLabel", header: t("provider.colDuration") },
93	    { key: "totalCents", header: t("admin.colAmount"), align: "right", sortable: true, sortValue: (r) => r.totalCents, render: (r) => formatCents(r.totalCents) },
94	    { key: "commissionCents", header: t("admin.colCommission"), align: "right", render: (r) => formatCents(r.commissionCents) },
95	    { key: "earningsCents", header: t("admin.colEarnings"), align: "right", render: (r) => formatCents(r.earningsCents) },
96	    { key: "status", header: t("admin.colStatus"), render: (r) => <StatusCell status={r.status} meta={SESSION_STATUS} /> },
97	  ];
98	  const paymentCols: Column<AdminPaymentRow>[] = [
99	    { key: "dateLabel", header: t("admin.colDate"), sortable: true, sortValue: (r) => r.dateMs },
100	    { key: "amountCents", header: t("admin.colAmount"), align: "right", sortable: true, sortValue: (r) => r.amountCents, render: (r) => formatCents(r.amountCents) },
101	    { key: "status", header: t("admin.colStatus"), render: (r) => <StatusCell status={r.status} meta={PAYMENT_STATUS} /> },
102	  ];
103	  const payoutCols: Column<AdminPayoutRow>[] = [
104	    { key: "periodLabel", header: t("provider.colPeriod"), sortable: true, sortValue: (r) => r.periodMs },
105	    { key: "amountCents", header: t("admin.colAmount"), align: "right", sortable: true, sortValue: (r) => r.amountCents, render: (r) => formatCents(r.amountCents) },
106	    { key: "status", header: t("admin.colStatus"), render: (r) => <StatusCell status={r.status} meta={PAYOUT_STATUS} /> },
107	  ];
108	
109	  return (
110	    <>
111	      <section className="flex flex-col gap-4">
112	        <h2 className="text-h2">{t("admin.sessionsHeading")}</h2>
113	        <DataTable caption={t("admin.sessionsCaption")} columns={sessionCols} rows={sessions} getRowKey={(r) => r.id} emptyText={t("admin.sessionsNone")} />
114	      </section>
115	      <section className="flex flex-col gap-4">
116	        <h2 className="text-h2">{t("admin.paymentsHeading")}</h2>
117	        <DataTable caption={t("admin.paymentsCaption")} columns={paymentCols} rows={payments} getRowKey={(r) => r.id} emptyText={t("admin.paymentsNone")} />
118	      </section>
119	      <section className="flex flex-col gap-4">
120	        <h2 className="text-h2">{t("admin.payoutsTableHeading")}</h2>
121	        <DataTable caption={t("admin.payoutsTableCaption")} columns={payoutCols} rows={payouts} getRowKey={(r) => r.id} emptyText={t("provider.payoutsNone")} />
122	      </section>
123	    </>
124	  );
125	}
